    // content, per the owner's original intent for Phase 5.
    //
    // Same 46 sounds as hiragana (Unit 1) — new shapes only, so this moves
    // faster: 5 lessons instead of hiragana's 10, rows bundled 2-3 per
    // lesson. The real new difficulty isn't sound acquisition, it's shape
    // confusion (シ/ツ, ソ/ン, ノ/メ) — see kana.ts's lookalikePairs and the
    // `contrast` fields below, which deliberately land the SECOND-taught
    // half of each pair (never the first, since nothing exists yet to
    // compare against) referencing back to the one already met.
